import numpy as np

def problem(x: np.ndarray) -> float:
    """
    Synthetic benchmark function combining a cubic term, a logarithmic barrier, and an interaction product.

    f(x) = 0.1 * sum(x**3) + 0.1 * log_barrier(x) + 0.4* x[0] * x[1] + 0.1 * np.sin(x[0]) + 0.1 * np.cos(x[1])

    where log_barrier(x) =  -sum(np.log(5 + x) + np.log(5 - x)) ensures that domain [-5,5]^N remains feasible.
    """

    def log_barrier(x):
        return -np.sum(np.log(5 + x) + np.log(5 - x))

    return 0.1 * np.sum(x**3) + 0.1 * log_barrier(x) + 0.4* x[0] * x[1] + 0.1 * np.sin(x[0]) + 0.1 * np.cos(x[1])
